AssistantMessageToolRequest(name='create', tool_call_id='tooluse_Btj9JswA6jhcsqd6imSIw3', arguments={'file_text': '/* =============================================
   COVE — Modern Retail — Base Styles
   ============================================= */

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --clr-brand:        #1a1a2e;
  --clr-accent:       #e63946;
  --clr-accent-dark:  #b52b35;
  --clr-surface:      #ffffff;
  --clr-surface-2:    #f4f4f6;
  --clr-surface-3:    #eaeaee;
  --clr-text:         #1a1a2e;
  --clr-text-muted:   #5a5a72;
  --clr-border:       #d0d0da;
  --clr-deal-bg:      #fff5f5;
  --clr-deal-badge:   #e63946;
  --radius-sm:        6px;
  --radius-md:        12px;
  --radius-lg:        20px;
  --shadow-card:      0 2px 8px rgba(0,0,0,.08), 0 0 1px rgba(0,0,0,.06);
  --shadow-card-hover:0 8px 24px rgba(0,0,0,.14), 0 0 1px rgba(0,0,0,.08);
  --transition:       200ms ease;
  --focus-ring:       0 0 0 3px #4a90e2;
  --font-sans:        'Inter', system-ui, -apple-system, sans-serif;
  --max-w:            1200px;
  --header-h:         64px;
}

/* ── Reduced motion ── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: .01ms !important; animation-duration: .01ms !important; }
}

/* ── Forced colors ── */
@media (forced-colors: active) {
  .btn-primary, .btn-outline { border: 2px solid ButtonText; }
  .product-card, .deal-card, .editorial-card { border: 1px solid ButtonText; }
  .badge { border: 1px solid ButtonText; }
  .nav-link::after { background: ButtonText; }
}

/* ── Base ── */
html { scroll-behavior: smooth; }
body {
  font-family: var(--font-sans);
  color: var(--clr-text);
  background: var(--clr-surface);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }

/* ── Skip link ── */
.skip-link {
  position: absolute;
  top: 0; left: 0;
  background: var(--clr-brand);
  color: #fff;
  padding: .75rem 1.25rem;
  border-radius: 0 0 var(--radius-sm) 0;
  font-weight: 600;
  z-index: 9999;
  transform: translateY(-100%);
  transition: transform var(--transition);
}
.skip-link:focus { transform: translateY(0); outline: 3px solid #4a90e2; outline-offset: 2px; }

/* ── Focus ring ── */
:focus-visible { outline: 3px solid #4a90e2; outline-offset: 2px; border-radius: 2px; }

/* ── Screen-reader only ── */
.sr-only:not(:focus):not(:active) {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}


/* =============================================
   HEADER
   ============================================= */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  height: var(--header-h);
  background: var(--clr-surface);
  border-bottom: 1px solid var(--clr-border);
  display: flex;
  align-items: center;
}
.header-inner {
  width: 100%;
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 0 1.5rem;
  display: flex;
  align-items: center;
  gap: 2rem;
}

/* Logo */
.logo {
  display: flex;
  align-items: center;
  gap: .5rem;
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: -.03em;
  color: var(--clr-brand);
  flex-shrink: 0;
}
.logo-mark {
  width: 32px; height: 32px;
  background: var(--clr-accent);
  border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  color: #fff;
  font-size: .95rem;
  font-weight: 900;
}

/* Primary nav */
.primary-nav { flex: 1; }
.primary-nav ul { display: flex; gap: .25rem; align-items: center; }
.nav-link {
  padding: .5rem .75rem;
  font-size: .9rem;
  font-weight: 500;
  color: var(--clr-text-muted);
  border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
  position: relative;
}
.nav-link::after {
  content: '';
  position: absolute;
  bottom: 2px; left: .75rem; right: .75rem;
  height: 2px;
  background: var(--clr-accent);
  border-radius: 2px;
  transform: scaleX(0);
  transition: transform var(--transition);
}
.nav-link:hover, .nav-link:focus-visible { color: var(--clr-text); background: var(--clr-surface-2); }
.nav-link[aria-current="page"] { color: var(--clr-accent); font-weight: 600; }
.nav-link[aria-current="page"]::after { transform: scaleX(1); }

/* Header actions */
.header-actions { display: flex; align-items: center; gap: .5rem; margin-left: auto; }
.icon-btn {
  display: flex; align-items: center; justify-content: center;
  width: 40px; height: 40px;
  border-radius: var(--radius-sm);
  color: var(--clr-text-muted);
  transition: color var(--transition), background var(--transition);
  position: relative;
}
.icon-btn:hover, .icon-btn:focus-visible { color: var(--clr-text); background: var(--clr-surface-2); }
.icon-btn svg { width: 20px; height: 20px; }
.cart-count {
  position: absolute;
  top: 4px; right: 4px;
  background: var(--clr-accent);
  color: #fff;
  font-size: .6rem;
  font-weight: 700;
  min-width: 16px; height: 16px;
  border-radius: 99px;
  display: flex; align-items: center; justify-content: center;
  padding: 0 3px;
  line-height: 1;
}

/* Mobile menu toggle — hidden on desktop */
.menu-toggle { display: none; }

/* Mobile nav */
.mobile-nav {
  display: none;
}


/* =============================================
   HERO
   ============================================= */
.hero {
  background: var(--clr-brand);
  color: #fff;
  overflow: hidden;
  position: relative;
}
.hero-inner {
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 5rem 1.5rem 4rem;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
}
.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  background: rgba(255,255,255,.12);
  border: 1px solid rgba(255,255,255,.18);
  padding: .35rem .9rem;
  border-radius: 99px;
  font-size: .78rem;
  font-weight: 600;
  letter-spacing: .06em;
  text-transform: uppercase;
  margin-bottom: 1.25rem;
}
.hero-eyebrow-dot { width: 6px; height: 6px; background: var(--clr-accent); border-radius: 50%; }
.hero h1 {
  font-size: clamp(2.2rem, 5vw, 3.4rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -.03em;
  margin-bottom: 1.25rem;
}
.hero h1 em { font-style: normal; color: var(--clr-accent); }
.hero-desc {
  font-size: 1.05rem;
  color: rgba(255,255,255,.75);
  max-width: 44ch;
  margin-bottom: 2rem;
}
.hero-cta { display: flex; gap: 1rem; flex-wrap: wrap; }
.btn-primary {
  display: inline-flex; align-items: center; gap: .5rem;
  padding: .85rem 1.75rem;
  background: var(--clr-accent);
  color: #fff;
  font-weight: 700;
  font-size: .95rem;
  border-radius: var(--radius-sm);
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
}
.btn-primary:hover { background: var(--clr-accent-dark); box-shadow: 0 4px 16px rgba(230,57,70,.35); transform: translateY(-1px); }
.btn-primary:active { transform: translateY(0); }
.btn-outline {
  display: inline-flex; align-items: center; gap: .5rem;
  padding: .85rem 1.75rem;
  background: transparent;
  color: #fff;
  font-weight: 600;
  font-size: .95rem;
  border: 2px solid rgba(255,255,255,.35);
  border-radius: var(--radius-sm);
  transition: border-color var(--transition), background var(--transition);
}
.btn-outline:hover { border-color: rgba(255,255,255,.8); background: rgba(255,255,255,.06); }

/* Hero visual */
.hero-visual {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}
.hero-img-wrap {
  width: 100%;
  max-width: 480px;
  aspect-ratio: 4/3;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: rgba(255,255,255,.08);
  display: flex; align-items: center; justify-content: center;
}
.hero-placeholder {
  width: 100%; height: 100%;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 1rem;
  color: rgba(255,255,255,.4);
  font-size: .85rem;
}
.hero-placeholder-icon { font-size: 4rem; opacity: .5; }

/* Hero stats */
.hero-stats {
  display: flex;
  gap: 2.5rem;
  margin-top: 2.5rem;
  padding-top: 2rem;
  border-top: 1px solid rgba(255,255,255,.12);
}
.hero-stat-value { font-size: 1.75rem; font-weight: 800; color: #fff; line-height: 1; }
.hero-stat-label { font-size: .78rem; color: rgba(255,255,255,.55); margin-top: .25rem; }


/* =============================================
   SECTION COMMON
   ============================================= */
.section { padding: 4.5rem 1.5rem; }
.section-inner { max-width: var(--max-w); margin: 0 auto; }
.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 2.25rem;
  gap: 1rem;
  flex-wrap: wrap;
}
.section-title { font-size: clamp(1.4rem, 3vw, 1.9rem); font-weight: 800; letter-spacing: -.02em; line-height: 1.2; }
.section-subtitle { color: var(--clr-text-muted); font-size: .9rem; margin-top: .35rem; }
.link-all {
  display: inline-flex; align-items: center; gap: .4rem;
  font-size: .875rem; font-weight: 600;
  color: var(--clr-accent);
  white-space: nowrap;
  border-radius: var(--radius-sm);
  padding: .25rem .5rem;
  transition: gap var(--transition);
}
.link-all:hover { gap: .7rem; }
.link-all svg { width: 16px; height: 16px; }


/* =============================================
   CATEGORY STRIP
   ============================================= */
.category-strip { padding: 1.5rem 1.5rem; background: var(--clr-surface-2); }
.category-list {
  max-width: var(--max-w);
  margin: 0 auto;
  display: flex;
  gap: .75rem;
  overflow-x: auto;
  padding-bottom: .25rem;
  scrollbar-width: none;
}
.category-list::-webkit-scrollbar { display: none; }
.category-chip {
  display: inline-flex; align-items: center; gap: .5rem;
  padding: .55rem 1.1rem;
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  border-radius: 99px;
  font-size: .85rem; font-weight: 500;
  white-space: nowrap;
  color: var(--clr-text-muted);
  transition: border-color var(--transition), color var(--transition), background var(--transition);
  cursor: pointer;
}
.category-chip:hover, .category-chip:focus-visible { border-color: var(--clr-accent); color: var(--clr-accent); background: var(--clr-deal-bg); }
.category-chip[aria-pressed="true"] { background: var(--clr-brand); color: #fff; border-color: var(--clr-brand); }
.category-chip-icon { font-size: 1rem; }


/* =============================================
   PRODUCT CARDS
   ============================================= */
.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1.5rem;
}

.product-card {
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex; flex-direction: column;
  transition: box-shadow var(--transition), transform var(--transition);
}
@media (prefers-reduced-motion: no-preference) {
  .product-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-card-hover); }
}
.product-card:not(:hover) { box-shadow: var(--shadow-card); }

.product-img-wrap {
  aspect-ratio: 1/1;
  background: var(--clr-surface-2);
  position: relative;
  overflow: hidden;
  display: flex; align-items: center; justify-content: center;
}
.product-placeholder {
  font-size: 4rem;
  opacity: .4;
  user-select: none;
  pointer-events: none;
}
.product-badge {
  position: absolute;
  top: .75rem; left: .75rem;
  background: var(--clr-accent);
  color: #fff;
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
  padding: .25rem .6rem;
  border-radius: 99px;
}
.product-badge.badge-new { background: var(--clr-brand); }
.product-badge.badge-sale { background: var(--clr-accent); }
.product-badge.badge-trending { background: #7c3aed; }

.product-body { padding: 1.1rem 1.1rem .75rem; flex: 1; display: flex; flex-direction: column; }
.product-category { font-size: .72rem; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: var(--clr-text-muted); margin-bottom: .35rem; }
.product-name-link {
  display: block;
  font-size: 1rem;
  font-weight: 700;
  line-height: 1.3;
  color: var(--clr-text);
  margin-bottom: .5rem;
  border-radius: 2px;
}
.product-name-link:hover { color: var(--clr-accent); }
.product-rating {
  display: flex; align-items: center; gap: .4rem;
  margin-bottom: .6rem;
}
.stars { color: #f59e0b; font-size: .85rem; letter-spacing: -.02em; }
.rating-count { font-size: .75rem; color: var(--clr-text-muted); }
.product-pricing { display: flex; align-items: baseline; gap: .5rem; margin-bottom: .8rem; margin-top: auto; }
.product-price { font-size: 1.2rem; font-weight: 800; color: var(--clr-text); }
.product-price-original { font-size: .85rem; color: var(--clr-text-muted); text-decoration: line-through; }
.product-price-save { font-size: .75rem; font-weight: 600; color: var(--clr-accent); background: var(--clr-deal-bg); padding: .15rem .45rem; border-radius: 4px; }

.product-footer { padding: 0 1.1rem 1.1rem; display: flex; gap: .5rem; }
.btn-add-cart {
  flex: 1;
  display: flex; align-items: center; justify-content: center; gap: .45rem;
  padding: .65rem .75rem;
  background: var(--clr-brand);
  color: #fff;
  font-size: .875rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  transition: background var(--transition), transform var(--transition);
}
.btn-add-cart:hover { background: #2d2d4e; }
.btn-add-cart:active { transform: scale(.97); }
.btn-add-cart svg { width: 16px; height: 16px; flex-shrink: 0; }
.btn-wishlist {
  display: flex; align-items: center; justify-content: center;
  width: 40px; height: auto;
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-sm);
  color: var(--clr-text-muted);
  transition: color var(--transition), border-color var(--transition), background var(--transition);
  flex-shrink: 0;
}
.btn-wishlist:hover { color: var(--clr-accent); border-color: var(--clr-accent); background: var(--clr-deal-bg); }
.btn-wishlist[aria-pressed="true"] { color: var(--clr-accent); background: var(--clr-deal-bg); border-color: var(--clr-accent); }
.btn-wishlist svg { width: 18px; height: 18px; }


/* =============================================
   DEALS SECTION
   ============================================= */
.deals-section { background: var(--clr-deal-bg); }
.deals-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.5rem;
}
.deal-card {
  background: var(--clr-surface);
  border: 1px solid rgba(230,57,70,.15);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: grid;
  grid-template-columns: 1fr 1fr;
  box-shadow: var(--shadow-card);
  transition: box-shadow var(--transition);
}
.deal-card:hover { box-shadow: var(--shadow-card-hover); }
.deal-card-body { padding: 1.75rem; display: flex; flex-direction: column; justify-content: space-between; }
.deal-tag {
  display: inline-flex; align-items: center; gap: .35rem;
  background: var(--clr-accent);
  color: #fff;
  font-size: .72rem;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  padding: .3rem .7rem;
  border-radius: 99px;
  margin-bottom: 1rem;
  width: fit-content;
}
.deal-card h3 { font-size: 1.25rem; font-weight: 800; line-height: 1.2; margin-bottom: .5rem; letter-spacing: -.02em; }
.deal-card p { font-size: .875rem; color: var(--clr-text-muted); margin-bottom: 1.25rem; line-height: 1.5; }
.deal-discount { font-size: 2rem; font-weight: 900; color: var(--clr-accent); line-height: 1; margin-bottom: .35rem; }
.deal-original { font-size: .85rem; color: var(--clr-text-muted); text-decoration: line-through; }

.deal-countdown {
  display: flex;
  gap: .5rem;
  margin-bottom: 1.25rem;
  align-items: center;
}
.deal-countdown-label { font-size: .72rem; font-weight: 600; color: var(--clr-text-muted); text-transform: uppercase; letter-spacing: .05em; }
.deal-time-block {
  background: var(--clr-brand);
  color: #fff;
  border-radius: var(--radius-sm);
  padding: .35rem .5rem;
  min-width: 36px;
  text-align: center;
}
.deal-time-value { font-size: .95rem; font-weight: 800; line-height: 1; display: block; }
.deal-time-unit { font-size: .58rem; letter-spacing: .04em; opacity: .7; display: block; margin-top: 1px; }
.deal-sep { font-weight: 800; color: var(--clr-accent); align-self: flex-start; padding-top: .3rem; }

.btn-deal {
  display: inline-flex; align-items: center; gap: .5rem;
  padding: .7rem 1.25rem;
  background: var(--clr-accent);
  color: #fff;
  font-size: .875rem; font-weight: 700;
  border-radius: var(--radius-sm);
  transition: background var(--transition);
  width: fit-content;
}
.btn-deal:hover { background: var(--clr-accent-dark); }
.btn-deal svg { width: 16px; height: 16px; }

.deal-card-img {
  background: var(--clr-surface-2);
  display: flex; align-items: center; justify-content: center;
  font-size: 5rem;
  opacity: .5;
}

/* Deal card wide (full width) */
.deal-card-wide {
  grid-column: span 2;
  grid-template-columns: 1fr 320px;
}
.deal-card-wide .deal-card-body { padding: 2.25rem 2rem; }
.deal-card-wide h3 { font-size: 1.6rem; }


/* =============================================
   PROMO BANNER
   ============================================= */
.promo-banner {
  background: var(--clr-brand);
  color: #fff;
  padding: 1rem 1.5rem;
  position: relative;
}
.promo-inner {
  max-width: var(--max-w);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1.5rem;
  text-align: center;
  flex-wrap: wrap;
}
.promo-text { font-size: .9rem; font-weight: 500; }
.promo-text strong { font-weight: 800; }
.promo-link { font-size: .875rem; font-weight: 700; color: #f4d03f; text-decoration: underline; }
.promo-dismiss {
  position: absolute; right: 1rem; top: 50%; transform: translateY(-50%);
  width: 32px; height: 32px;
  display: flex; align-items: center; justify-content: center;
  border-radius: var(--radius-sm);
  color: rgba(255,255,255,.65);
  transition: color var(--transition), background var(--transition);
}
.promo-dismiss:hover { color: #fff; background: rgba(255,255,255,.12); }
.promo-dismiss svg { width: 18px; height: 18px; }


/* =============================================
   EDITORIAL SECTION
   ============================================= */
.editorial-section { background: var(--clr-surface-2); }
.editorial-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 1.5rem;
}
.editorial-card {
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex; flex-direction: column;
  box-shadow: var(--shadow-card);
  transition: box-shadow var(--transition);
}
.editorial-card:hover { box-shadow: var(--shadow-card-hover); }
.editorial-card-img {
  aspect-ratio: 16/9;
  background: var(--clr-surface-3);
  display: flex; align-items: center; justify-content: center;
  font-size: 3.5rem;
  overflow: hidden;
}
.editorial-card-featured .editorial-card-img { aspect-ratio: 16/9; font-size: 6rem; }
.editorial-card-body { padding: 1.5rem; flex: 1; display: flex; flex-direction: column; }
.editorial-tag {
  display: inline-flex;
  background: var(--clr-surface-3);
  color: var(--clr-text-muted);
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .06em;
  text-transform: uppercase;
  padding: .25rem .6rem;
  border-radius: 4px;
  margin-bottom: .75rem;
  width: fit-content;
}
.editorial-card h3 { font-size: 1.05rem; font-weight: 700; line-height: 1.3; margin-bottom: .5rem; letter-spacing: -.01em; }
.editorial-card-featured h3 { font-size: 1.3rem; }
.editorial-excerpt { font-size: .875rem; color: var(--clr-text-muted); line-height: 1.55; flex: 1; margin-bottom: 1.1rem; }
.editorial-meta {
  display: flex; align-items: center; justify-content: space-between;
  font-size: .75rem;
  color: var(--clr-text-muted);
  padding-top: .9rem;
  border-top: 1px solid var(--clr-border);
  margin-top: auto;
}
.editorial-author { display: flex; align-items: center; gap: .5rem; font-weight: 600; color: var(--clr-text); }
.author-avatar {
  width: 26px; height: 26px;
  border-radius: 50%;
  background: var(--clr-brand);
  color: #fff;
  font-size: .65rem;
  font-weight: 800;
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
  aria-hidden: true;
}
.editorial-read-link {
  display: inline-flex; align-items: center; gap: .35rem;
  color: var(--clr-accent);
  font-weight: 700;
  font-size: .82rem;
  border-radius: 2px;
  padding: .15rem .3rem;
}
.editorial-read-link:hover { text-decoration: underline; }
.editorial-read-link svg { width: 14px; height: 14px; }


/* =============================================
   TRUST STRIP
   ============================================= */
.trust-strip { background: var(--clr-surface); border-top: 1px solid var(--clr-border); border-bottom: 1px solid var(--clr-border); padding: 2rem 1.5rem; }
.trust-list {
  max-width: var(--max-w);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.5rem;
}
.trust-item {
  display: flex; flex-direction: column; align-items: center;
  text-align: center; gap: .6rem;
}
.trust-icon { font-size: 1.75rem; line-height: 1; }
.trust-label { font-size: .85rem; font-weight: 700; color: var(--clr-text); }
.trust-desc { font-size: .78rem; color: var(--clr-text-muted); line-height: 1.4; }


/* =============================================
   NEWSLETTER
   ============================================= */
.newsletter-section {
  background: var(--clr-brand);
  color: #fff;
  padding: 4rem 1.5rem;
}
.newsletter-inner {
  max-width: 560px;
  margin: 0 auto;
  text-align: center;
}
.newsletter-inner h2 { font-size: clamp(1.5rem, 3vw, 2rem); font-weight: 800; letter-spacing: -.02em; margin-bottom: .75rem; }
.newsletter-inner p { font-size: .95rem; color: rgba(255,255,255,.72); margin-bottom: 1.75rem; }
.newsletter-form {
  display: flex; gap: .75rem;
  max-width: 440px; margin: 0 auto;
}
.newsletter-input-wrap { flex: 1; position: relative; }
.newsletter-label {
  position: absolute;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px; overflow: hidden;
  white-space: nowrap; width: 1px;
}
.newsletter-input {
  width: 100%;
  padding: .85rem 1rem;
  background: rgba(255,255,255,.1);
  border: 1.5px solid rgba(255,255,255,.25);
  border-radius: var(--radius-sm);
  color: #fff;
  font-size: .9rem; font-family: inherit;
  transition: border-color var(--transition);
}
.newsletter-input::placeholder { color: rgba(255,255,255,.45); }
.newsletter-input:focus { outline: none; border-color: rgba(255,255,255,.8); }
.newsletter-input:focus-visible { outline: 3px solid #4a90e2; outline-offset: 2px; }
.newsletter-submit {
  padding: .85rem 1.5rem;
  background: var(--clr-accent);
  color: #fff;
  font-weight: 700;
  font-size: .875rem;
  border-radius: var(--radius-sm);
  white-space: nowrap;
  transition: background var(--transition);
}
.newsletter-submit:hover { background: var(--clr-accent-dark); }
.newsletter-status {
  min-height: 1.5rem;
  margin-top: .9rem;
  font-size: .85rem;
  font-weight: 600;
}
.newsletter-status[data-state="success"] { color: #6ee7b7; }
.newsletter-status[data-state="error"] { color: #fca5a5; }
.newsletter-note { font-size: .75rem; color: rgba(255,255,255,.45); margin-top: .75rem; }


/* =============================================
   FOOTER
   ============================================= */
.site-footer {
  background: #0f0f1f;
  color: rgba(255,255,255,.7);
  padding: 3.5rem 1.5rem 1.5rem;
}
.footer-inner {
  max-width: var(--max-w);
  margin: 0 auto;
}
.footer-top {
  display: grid;
  grid-template-columns: 1.4fr repeat(3, 1fr);
  gap: 3rem;
  padding-bottom: 2.5rem;
  border-bottom: 1px solid rgba(255,255,255,.08);
  margin-bottom: 2rem;
}
.footer-brand .logo { color: #fff; margin-bottom: 1rem; }
.footer-tagline { font-size: .875rem; line-height: 1.6; color: rgba(255,255,255,.5); max-width: 26ch; }
.footer-col-title {
  font-size: .8rem;
  font-weight: 700;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: #fff;
  margin-bottom: 1.1rem;
}
.footer-nav-list { display: flex; flex-direction: column; gap: .55rem; }
.footer-nav-link {
  font-size: .875rem;
  color: rgba(255,255,255,.55);
  border-radius: 2px;
  transition: color var(--transition);
}
.footer-nav-link:hover { color: #fff; }
.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1rem;
  font-size: .78rem;
  color: rgba(255,255,255,.35);
}
.footer-legal { display: flex; gap: 1.25rem; }
.footer-legal a { color: rgba(255,255,255,.35); transition: color var(--transition); }
.footer-legal a:hover { color: rgba(255,255,255,.75); }

/* Social icons */
.social-links { display: flex; gap: .5rem; margin-top: 1.1rem; }
.social-link {
  width: 34px; height: 34px;
  border-radius: var(--radius-sm);
  border: 1px solid rgba(255,255,255,.12);
  display: flex; align-items: center; justify-content: center;
  color: rgba(255,255,255,.5);
  font-size: .75rem; font-weight: 800;
  transition: color var(--transition), border-color var(--transition);
}
.social-link:hover { color: #fff; border-color: rgba(255,255,255,.4); }


/* =============================================
   CART NOTIFICATION (live region)
   ============================================= */
.cart-toast {
  position: fixed;
  bottom: 1.5rem; right: 1.5rem;
  background: var(--clr-brand);
  color: #fff;
  padding: .85rem 1.25rem;
  border-radius: var(--radius-md);
  box-shadow: 0 8px 30px rgba(0,0,0,.2);
  font-size: .875rem; font-weight: 600;
  display: flex; align-items: center; gap: .6rem;
  z-index: 500;
  transform: translateY(150%);
  transition: transform 300ms cubic-bezier(.34,1.56,.64,1);
  pointer-events: none;
}
.cart-toast.show { transform: translateY(0); }
.cart-toast-icon { font-size: 1.1rem; }


/* =============================================
   RESPONSIVE
   ============================================= */
@media (max-width: 1024px) {
  .deals-grid { grid-template-columns: 1fr; }
  .deal-card-wide { grid-column: span 1; grid-template-columns: 1fr 240px; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .editorial-card-featured { grid-column: span 2; }
  .footer-top { grid-template-columns: 1fr 1fr; gap: 2rem; }
}

@media (max-width: 768px) {
  :root { --header-h: 56px; }

  /* Mobile nav */
  .primary-nav { display: none; }
  .primary-nav.is-open {
    display: block;
    position: absolute;
    top: var(--header-h); left: 0; right: 0;
    background: var(--clr-surface);
    border-bottom: 1px solid var(--clr-border);
    padding: 1rem;
    z-index: 99;
    box-shadow: 0 4px 20px rgba(0,0,0,.1);
  }
  .primary-nav.is-open ul { flex-direction: column; }
  .primary-nav.is-open .nav-link { display: block; padding: .75rem 1rem; font-size: 1rem; }
  .menu-toggle { display: flex; align-items: center; justify-content: center; width: 40px; height: 40px; border-radius: var(--radius-sm); color: var(--clr-text-muted); }
  .menu-toggle:hover { background: var(--clr-surface-2); color: var(--clr-text); }
  .menu-toggle svg { width: 22px; height: 22px; }

  .hero-inner { grid-template-columns: 1fr; padding: 3rem 1.25rem 2.5rem; gap: 2rem; }
  .hero-visual { order: -1; }
  .hero-img-wrap { max-width: 100%; aspect-ratio: 16/9; }
  .hero-stats { gap: 1.5rem; }

  .deals-grid { grid-template-columns: 1fr; }
  .deal-card, .deal-card-wide { grid-template-columns: 1fr; }
  .deal-card-wide { grid-column: span 1; }
  .deal-card-img { aspect-ratio: 16/9; font-size: 4rem; }

  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-card-featured { grid-column: span 1; }

  .trust-list { grid-template-columns: 1fr 1fr; }

  .newsletter-form { flex-direction: column; }
  .newsletter-submit { width: 100%; }

  .footer-top { grid-template-columns: 1fr; gap: 2rem; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
}

@media (max-width: 480px) {
  .products-grid { grid-template-columns: 1fr 1fr; }
  .trust-list { grid-template-columns: 1fr; }
  .hero-stats { flex-direction: column; gap: 1rem; }
}

@media (max-width: 320px) {
  .products-grid { grid-template-columns: 1fr; }
  .hero h1 { font-size: 1.9rem; }
  .deal-card-body { padding: 1.25rem; }
}
