+}
+
+/* Primary nav */
+.primary-nav { flex: 1; }
+.primary-nav ul { display: flex; gap: .25rem; align-items: center; }
+.nav-link {
+  padding: .5rem .75rem;
+  font-size: .9rem;
+  font-weight: 500;
+  color: var(--clr-text-muted);
