+
+/* Deal card wide (full width) */
+.deal-card-wide {
+  grid-column: span 2;
+  grid-template-columns: 1fr 320px;
+}
+.deal-card-wide .deal-card-body { padding: 2.25rem 2rem; }
+.deal-card-wide h3 { font-size: 1.6rem; }
+
+
+/* =============================================
+   PROMO BANNER
+   ============================================= */
+.promo-banner {
+  background: var(--clr-brand);
+  color: #fff;
+  padding: 1rem 1.5rem;
+  position: relative;
+}
+.promo-inner {
+  max-width: var(--max-w);
+  margin: 0 auto;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  gap: 1.5rem;
+  text-align: center;
+  flex-wrap: wrap;
