+.trust-desc { font-size: .78rem; color: var(--clr-text-muted); line-height: 1.4; }
+
+
+/* =============================================
+   NEWSLETTER
+   ============================================= */
+.newsletter-section {
+  background: var(--clr-brand);
+  color: #fff;
+  padding: 4rem 1.5rem;
+}
+.newsletter-inner {
