   COVE — Modern Retail — Base Styles
   ============================================= */

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --clr-brand:        #1a1a2e;
  --clr-accent:       #e63946;
  --clr-accent-dark:  #b52b35;
  --clr-surface:      #ffffff;
  --clr-surface-2:    #f4f4f6;
  --clr-surface-3:    #eaeaee;
  --clr-text:         #1a1a2e;
  --clr-text-muted:   #5a5a72;
  --clr-border:       #d0d0da;
  --clr-deal-bg:      #fff5f5;
  --clr-deal-badge:   #e63946;
  --radius-sm:        6px;
  --radius-md:        12px;
  --radius-lg:        20px;
  --shadow-card:      0 2px 8px rgba(0,0,0,.08), 0 0 1px rgba(0,0,0,.06);
  --shadow-card-hover:0 8px 24px rgba(0,0,0,.14), 0 0 1px rgba(0,0,0,.08);
  --transition:       200ms ease;
  --focus-ring:       0 0 0 3px #4a90e2;
  --font-sans:        'Inter', system-ui, -apple-system, sans-serif;
  --max-w:            1200px;
  --header-h:         64px;
}

/* ── Reduced motion ── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: .01ms !important; animation-duration: .01ms !important; }
}

/* ── Forced colors ── */
@media (forced-colors: active) {
  .btn-primary, .btn-outline { border: 2px solid ButtonText; }
  .product-card, .deal-card, .editorial-card { border: 1px solid ButtonText; }
  .badge { border: 1px solid ButtonText; }
  .nav-link::after { background: ButtonText; }
}

/* ── Base ── */
html { scroll-behavior: smooth; }
body {
  font-family: var(--font-sans);
  color: var(--clr-text);
  background: var(--clr-surface);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }

/* ── Skip link ── */
.skip-link {
  position: absolute;
  top: 0; left: 0;
  background: var(--clr-brand);
  color: #fff;
  padding: .75rem 1.25rem;
  border-radius: 0 0 var(--radius-sm) 0;
  font-weight: 600;
  z-index: 9999;
  transform: translateY(-100%);
  transition: transform var(--transition);
}
.skip-link:focus { transform: translateY(0); outline: 3px solid #4a90e2; outline-offset: 2px; }

/* ── Focus ring ── */
:focus-visible { outline: 3px solid #4a90e2; outline-offset: 2px; border-radius: 2px; }

/* ── Screen-reader only ── */
.sr-only:not(:focus):not(:active) {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}


/* =============================================
   HEADER
   ============================================= */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  height: var(--header-h);
  background: var(--clr-surface);
  border-bottom: 1px solid var(--clr-border);
  display: flex;
  align-items: center;
}
.header-inner {
  width: 100%;
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 0 1.5rem;
  display: flex;
  align-items: center;
  gap: 2rem;
}

/* Logo */
.logo {
  display: flex;
  align-items: center;
  gap: .5rem;
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: -.03em;
  color: var(--clr-brand);
  flex-shrink: 0;
}
.logo-mark {
  width: 32px; height: 32px;
  background: var(--clr-accent);
  border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  color: #fff;
  font-size: .95rem;
  font-weight: 900;
}

/* Primary nav */
.primary-nav { flex: 1; }
.primary-nav ul { display: flex; gap: .25rem; align-items: center; }
.nav-link {
  padding: .5rem .75rem;
  font-size: .9rem;
  font-weight: 500;
  color: var(--clr-text-muted);
  border-radius: var(--radius-sm);
  transition: color var(--transition), background var(--transition);
  position: relative;
}
.nav-link::after {
  content: '';
  position: absolute;
  bottom: 2px; left: .75rem; right: .75rem;
  height: 2px;
  background: var(--clr-accent);
  border-radius: 2px;
  transform: scaleX(0);
  transition: transform var(--transition);
}
.nav-link:hover, .nav-link:focus-visible { color: var(--clr-text); background: var(--clr-surface-2); }
.nav-link[aria-current="page"] { color: var(--clr-accent); font-weight: 600; }
.nav-link[aria-current="page"]::after { transform: scaleX(1); }

/* Header actions */
.header-actions { display: flex; align-items: center; gap: .5rem; margin-left: auto; }
.icon-btn {
  display: flex; align-items: center; justify-content: center;
  width: 40px; height: 40px;
  border-radius: var(--radius-sm);
  color: var(--clr-text-muted);
  transition: color var(--transition), background var(--transition);
  position: relative;
}
.icon-btn:hover, .icon-btn:focus-visible { color: var(--clr-text); background: var(--clr-surface-2); }
.icon-btn svg { width: 20px; height: 20px; }
.cart-count {
  position: absolute;
  top: 4px; right: 4px;
  background: var(--clr-accent);
  color: #fff;
  font-size: .6rem;
  font-weight: 700;
  min-width: 16px; height: 16px;
  border-radius: 99px;
  display: flex; align-items: center; justify-content: center;
  padding: 0 3px;
  line-height: 1;
}

/* Mobile menu toggle — hidden on desktop */
.menu-toggle { display: none; }

/* Mobile nav */
.mobile-nav {
  display: none;
}


/* =============================================
   HERO
   ============================================= */
.hero {
  background: var(--clr-brand);
  color: #fff;
  overflow: hidden;
  position: relative;
}
.hero-inner {
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 5rem 1.5rem 4rem;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
}
.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: .5rem;
  background: rgba(255,255,255,.12);
  border: 1px solid rgba(255,255,255,.18);
  padding: .35rem .9rem;
  border-radius: 99px;
  font-size: .78rem;
  font-weight: 600;
  letter-spacing: .06em;
  text-transform: uppercase;
  margin-bottom: 1.25rem;
}
.hero-eyebrow-dot { width: 6px; height: 6px; background: var(--clr-accent); border-radius: 50%; }
.hero h1 {
  font-size: clamp(2.2rem, 5vw, 3.4rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -.03em;
  margin-bottom: 1.25rem;
}
.hero h1 em { font-style: normal; color: var(--clr-accent); }
.hero-desc {
  font-size: 1.05rem;
  color: rgba(255,255,255,.75);
  max-width: 44ch;
  margin-bottom: 2rem;
}
.hero-cta { display: flex; gap: 1rem; flex-wrap: wrap; }
.btn-primary {
  display: inline-flex; align-items: center; gap: .5rem;
  padding: .85rem 1.75rem;
  background: var(--clr-accent);
  color: #fff;
  font-weight: 700;
  font-size: .95rem;
  border-radius: var(--radius-sm);
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
}
.btn-primary:hover { background: var(--clr-accent-dark); box-shadow: 0 4px 16px rgba(230,57,70,.35); transform: translateY(-1px); }
.btn-primary:active { transform: translateY(0); }
.btn-outline {
  display: inline-flex; align-items: center; gap: .5rem;
  padding: .85rem 1.75rem;
  background: transparent;
  color: #fff;
  font-weight: 600;
  font-size: .95rem;
  border: 2px solid rgba(255,255,255,.35);
  border-radius: var(--radius-sm);
  transition: border-color var(--transition), background var(--transition);
}
.btn-outline:hover { border-color: rgba(255,255,255,.8); background: rgba(255,255,255,.06); }

/* Hero visual */
.hero-visual {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}
.hero-img-wrap {
  width: 100%;
  max-width: 480px;
  aspect-ratio: 4/3;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: rgba(255,255,255,.08);
  display: flex; align-items: center; justify-content: center;
}
.hero-placeholder {
  width: 100%; height: 100%;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 1rem;
  color: rgba(255,255,255,.4);
  font-size: .85rem;
}
.hero-placeholder-icon { font-size: 4rem; opacity: .5; }

/* Hero stats */
.hero-stats {
  display: flex;
  gap: 2.5rem;
  margin-top: 2.5rem;
  padding-top: 2rem;
  border-top: 1px solid rgba(255,255,255,.12);
}
.hero-stat-value { font-size: 1.75rem; font-weight: 800; color: #fff; line-height: 1; }
.hero-stat-label { font-size: .78rem; color: rgba(255,255,255,.55); margin-top: .25rem; }


/* =============================================
   SECTION COMMON
   ============================================= */
.section { padding: 4.5rem 1.5rem; }
.section-inner { max-width: var(--max-w); margin: 0 auto; }
.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 2.25rem;
  gap: 1rem;
  flex-wrap: wrap;
}
.section-title { font-size: clamp(1.4rem, 3vw, 1.9rem); font-weight: 800; letter-spacing: -.02em; line-height: 1.2; }
.section-subtitle { color: var(--clr-text-muted); font-size: .9rem; margin-top: .35rem; }
.link-all {
  display: inline-flex; align-items: center; gap: .4rem;
  font-size: .875rem; font-weight: 600;
  color: var(--clr-accent);
  white-space: nowrap;
  border-radius: var(--radius-sm);
  padding: .25rem .5rem;
  transition: gap var(--transition);
}
.link-all:hover { gap: .7rem; }
.link-all svg { width: 16px; height: 16px; }


/* =============================================
   CATEGORY STRIP
   ============================================= */
.category-strip { padding: 1.5rem 1.5rem; background: var(--clr-surface-2); }
.category-list {
  max-width: var(--max-w);
  margin: 0 auto;
  display: flex;
  gap: .75rem;
  overflow-x: auto;
  padding-bottom: .25rem;
  scrollbar-width: none;
}
.category-list::-webkit-scrollbar { display: none; }
.category-chip {
  display: inline-flex; align-items: center; gap: .5rem;
  padding: .55rem 1.1rem;
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  border-radius: 99px;
  font-size: .85rem; font-weight: 500;
  white-space: nowrap;
  color: var(--clr-text-muted);
  transition: border-color var(--transition), color var(--transition), background var(--transition);
  cursor: pointer;
}
.category-chip:hover, .category-chip:focus-visible { border-color: var(--clr-accent); color: var(--clr-accent); background: var(--clr-deal-bg); }
.category-chip[aria-pressed="true"] { background: var(--clr-brand); color: #fff; border-color: var(--clr-brand); }
.category-chip-icon { font-size: 1rem; }


/* =============================================
   PRODUCT CARDS
   ============================================= */
.products-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1.5rem;
}

.product-card {
  background: var(--clr-surface);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex; flex-direction: column;
  transition: box-shadow var(--transition), transform var(--transition);
}
@media (prefers-reduced-motion: no-preference) {
  .product-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-card-hover); }
}
.product-card:not(:hover) { box-shadow: var(--shadow-card); }

.product-img-wrap {
  aspect-ratio: 1/1;
  background: var(--clr-surface-2);
  position: relative;
  overflow: hidden;
  display: flex; align-items: center; justify-content: center;
}
.product-placeholder {
  font-size: 4rem;
  opacity: .4;
  user-select: none;
  pointer-events: none;
}
.product-badge {
  position: absolute;
  top: .75rem; left: .75rem;
  background: var(--clr-accent);
  color: #fff;
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
  padding: .25rem .6rem;
  border-radius: 99px;
}
.product-badge.badge-new { background: var(--clr-brand); }
.product-badge.badge-sale { background: var(--clr-accent); }
