}
.newsletter-inner h2 { font-size: clamp(1.5rem, 3vw, 2rem); font-weight: 800; letter-spacing: -.02em; margin-bottom: .75rem; }
.newsletter-inner p { font-size: .95rem; color: rgba(255,255,255,.72); margin-bottom: 1.75rem; }
