    categoryChips.forEach(c => c.setAttribute('aria-pressed', 'false'));
    if (!isPressed) chip.setAttribute('aria-pressed', 'true');
  });
  chip.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); chip.click(); }
  });
});

// ── Wishlist toggle ───────────────────────────
const wishlistBtns = document.querySelectorAll('.btn-wishlist');
wishlistBtns.forEach(btn => {
  btn.addEventListener('click', () => {
    const pressed = btn.getAttribute('aria-pressed') === 'true';
    btn.setAttribute('aria-pressed', String(!pressed));
    const productName = btn.dataset.product || 'item';
    announceStatus(pressed ? `Removed ${productName} from wishlist` : `Saved ${productName} to wishlist`);
  });
});

// ── Add to cart ───────────────────────────────
let cartCount = 0;
const cartCountEl = document.getElementById('cart-count');
const cartToast = document.getElementById('cart-toast');
const cartToastText = document.getElementById('cart-toast-text');
const cartStatus = document.getElementById('cart-status');

function updateCartCount(n) {
  cartCount = n;
  if (cartCountEl) {
    cartCountEl.textContent = n;
    cartCountEl.hidden = n === 0;
  }
