+function updateCountdown() {
+  const now = new Date();
+  // Count down to midnight
+  const midnight = new Date(now);
+  midnight.setHours(24, 0, 0, 0);
+  const diff = Math.max(0, Math.floor((midnight - now) / 1000));
+
+  const h = Math.floor(diff / 3600);
+  const m = Math.floor((diff % 3600) / 60);
+  const s = diff % 60;
+
+  const pad = n => String(n).padStart(2, '0');
+
+  const hEl = document.getElementById('cd-hours');
+  const mEl = document.getElementById('cd-mins');
+  const sEl = document.getElementById('cd-secs');
+  if (hEl) hEl.textContent = pad(h);
+  if (mEl) mEl.textContent = pad(m);
+  if (sEl) sEl.textContent = pad(s);
+
+  // Update accessible label for screen readers (throttled to once per minute)
+  const cdRegion = document.getElementById('countdown-sr');
+  if (cdRegion && s === 0) {
+    cdRegion.textContent = `Deal ends in ${pad(h)} hours and ${pad(m)} minutes`;
+  }
+}
+
+updateCountdown();
+setInterval(updateCountdown, 1000);
+
+// ── Newsletter form ───────────────────────────
+const newsletterForm = document.getElementById('newsletter-form');
+const newsletterStatus = document.getElementById('newsletter-status');
+if (newsletterForm && newsletterStatus) {
+  newsletterForm.addEventListener('submit', (e) => {
+    e.preventDefault();
+    const input = newsletterForm.querySelector('.newsletter-input');
+    const email = input ? input.value.trim() : '';
+    if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
+      newsletterStatus.textContent = 'Please enter a valid email address.';
+      newsletterStatus.dataset.state = 'error';
+      input && input.focus();
+      return;
+    }
+    // Simulate success
+    newsletterStatus.textContent = '🎉 You\'re in! Check your inbox for a welcome discount.';
+    newsletterStatus.dataset.state = 'success';
+    if (input) input.value = '';
+  });
+}
+
