const { chromium } = require('playwright');
const axe = require('axe-core');
const path = require('path');
const fs = require('fs');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const htmlPath = 'file://' + path.resolve('index.html');
  await page.goto(htmlPath, { waitUntil: 'load' });
  await page.addScriptTag({ content: axe.source });
  const results = await page.evaluate(async () => await window.axe.run());
  await browser.close();

  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bp   = results.violations.filter(v =>  v.tags.includes('best-practice'));

  console.log('=== WCAG violations (' + wcag.length + ') ===');
  wcag.forEach(v => {
    console.log('[' + v.impact.toUpperCase() + '] ' + v.id + ': ' + v.description);
    v.nodes.forEach(n => console.log('  target:', JSON.stringify(n.target), '| fix:', n.failureSummary.split('\n')[0]));
  });
  console.log('\n=== Best-practice (' + bp.length + ') ===');
  bp.forEach(v => {
    console.log('[BP] ' + v.id + ': ' + v.description);
    v.nodes.forEach(n => console.log('  target:', JSON.stringify(n.target)));
  });
  process.exit(wcag.length ? 1 : 0);
})();
