}
.btn-outline:hover { border-color: rgba(255,255,255,.8); background: rgba(255,255,255,.06); }

/* Hero visual */
.hero-visual {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}
.hero-img-wrap {
  width: 100%;
