*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --clr-brand:        #1a1a2e;
  --clr-accent:       #c0392b;
  --clr-accent-dark:  #a93226;
  --clr-surface:      #ffffff;
