   COVE — Modern Retail — Base Styles
   ============================================= */

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --clr-brand:        #1a1a2e;
  --clr-accent:       #c0392b;
  --clr-accent-dark:  #a93226;
  --clr-surface:      #ffffff;
  --clr-surface-2:    #f4f4f6;
  --clr-surface-3:    #eaeaee;
  --clr-text:         #1a1a2e;
  --clr-text-muted:   #5a5a72;
  --clr-border:       #d0d0da;
  --clr-deal-bg:      #fff5f5;
  --clr-deal-badge:   #c0392b;
  --radius-sm:        6px;
